package com.cowave.search.common.exception

import org.springframework.http.HttpStatus

/**
 * DSearch 애플리케이션의 기본 예외 클래스.
 * 모든 커스텀 예외는 이 클래스를 상속한다.
 */
sealed class DSearchException(
    message: String,
    val status: HttpStatus,
    cause: Throwable? = null,
) : RuntimeException(message, cause)

// ── 400 Bad Request ─────────────────────────────────────────────

class ElasticQueryException(
    message: String,
    cause: Throwable? = null,
) : DSearchException(message, HttpStatus.BAD_REQUEST, cause)

class NotFoundException(
    message: String,
) : DSearchException(message, HttpStatus.BAD_REQUEST)

class NotFoundUserException(
    message: String,
) : DSearchException(message, HttpStatus.BAD_REQUEST)

class DuplicatedUserException(
    message: String,
) : DSearchException(message, HttpStatus.BAD_REQUEST)

class InvalidPasswordException(
    message: String,
) : DSearchException(message, HttpStatus.BAD_REQUEST)

class ParameterInvalidException(
    message: String,
) : DSearchException(message, HttpStatus.BAD_REQUEST)

class CronParseException(
    message: String,
    cause: Throwable? = null,
) : DSearchException(message, HttpStatus.BAD_REQUEST, cause)

class ConvertYamlException(
    message: String,
    cause: Throwable? = null,
) : DSearchException(message, HttpStatus.BAD_REQUEST, cause)

class NoSuchAnalyzerException(
    message: String,
) : DSearchException(message, HttpStatus.BAD_REQUEST)

// ── 401 Unauthorized ────────────────────────────────────────────

class PermissionException(
    message: String,
) : DSearchException(message, HttpStatus.UNAUTHORIZED)

// ── 500 Internal Server Error ───────────────────────────────────

class IndexingJobFailureException(
    message: String,
    cause: Throwable? = null,
) : DSearchException(message, HttpStatus.INTERNAL_SERVER_ERROR, cause)

class ServiceException(
    message: String,
    cause: Throwable? = null,
) : DSearchException(message, HttpStatus.INTERNAL_SERVER_ERROR, cause)

package com.cowave.search.common.security

import jakarta.servlet.FilterChain
import jakarta.servlet.http.HttpServletRequest
import jakarta.servlet.http.HttpServletResponse
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken
import org.springframework.security.core.authority.SimpleGrantedAuthority
import org.springframework.security.core.context.SecurityContextHolder
import org.springframework.web.filter.OncePerRequestFilter

/**
 * JWT 인증 필터.
 *
 * - x-bearer-token 헤더에서 JWT 토큰 추출 및 검증
 * - 검증 성공 시 SecurityContextHolder에 인증 정보 저장
 * - 토큰 만료 절반 경과 시 응답 헤더에 갱신된 토큰 반환
 * - bypassUri 경로는 SecurityFilterChain에서 permitAll 처리되므로 이 필터는 authenticated() 경로만 진입
 */
class JwtAuthenticationFilter(
    private val jwtUtils: JwtUtils,
) : OncePerRequestFilter() {
    override fun doFilterInternal(
        request: HttpServletRequest,
        response: HttpServletResponse,
        filterChain: FilterChain,
    ) {
        val token = request.getHeader(JwtUtils.TOKEN_HEADER)

        if (token != null) {
            val claims = jwtUtils.verify(token)
            if (claims != null) {
                // SecurityContextHolder에 인증 정보 저장
                val authorities =
                    claims.roleId?.let { listOf(SimpleGrantedAuthority("ROLE_USER")) }
                        ?: emptyList()
                val authentication =
                    UsernamePasswordAuthenticationToken(
                        claims.email,
                        null,
                        authorities,
                    )
                authentication.details = claims
                SecurityContextHolder.getContext().authentication = authentication

                // 토큰 갱신 필요 시 응답 헤더에 새 토큰 세팅
                if (jwtUtils.needsRefresh(token)) {
                    jwtUtils.refresh(token)?.let { newToken ->
                        response.setHeader(JwtUtils.TOKEN_HEADER, newToken)
                    }
                }
            }
            // 토큰이 있지만 검증 실패한 경우 → SecurityContext가 비어있으므로
            // SecurityFilterChain의 authenticated() 규칙에 의해 401 반환
        }

        filterChain.doFilter(request, response)
    }
}

package com.cowave.search.config

import com.cowave.search.common.security.JwtAuthenticationFilter
import com.cowave.search.common.security.JwtProperties
import com.cowave.search.common.security.JwtUtils
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.http.HttpStatus
import org.springframework.security.config.annotation.web.builders.HttpSecurity
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity
import org.springframework.security.config.http.SessionCreationPolicy
import org.springframework.security.web.SecurityFilterChain
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter

@Configuration
@EnableWebSecurity
class SecurityConfig(
    private val jwtUtils: JwtUtils,
    private val jwtProperties: JwtProperties,
) {
    @Bean
    fun jwtAuthenticationFilter(): JwtAuthenticationFilter = JwtAuthenticationFilter(jwtUtils)

    @Bean
    fun securityFilterChain(http: HttpSecurity): SecurityFilterChain {
        val bypassUris = jwtProperties.bypassUri.toTypedArray()

        http
            .csrf { it.disable() }
            .sessionManagement { it.sessionCreationPolicy(SessionCreationPolicy.STATELESS) }
            .authorizeHttpRequests { auth ->
                // bypassUri 경로는 인증 없이 허용 (2차 방어: Spring Security 레벨)
                auth.requestMatchers(*bypassUris).permitAll()
                // 나머지 모든 경로는 인증 필요
                auth.anyRequest().authenticated()
            }
            // JWT 필터를 UsernamePasswordAuthenticationFilter 앞에 등록
            .addFilterBefore(jwtAuthenticationFilter(), UsernamePasswordAuthenticationFilter::class.java)
            // 인증 실패 처리: 401 반환 (Spring Security 기본 리다이렉트 방지)
            .exceptionHandling { ex ->
                ex.authenticationEntryPoint { _, response, _ ->
                    response.status = HttpStatus.UNAUTHORIZED.value()
                    response.contentType = "application/json;charset=UTF-8"
                    response.writer.write("""{"message":"Unauthorized"}""")
                }
            }

        return http.build()
    }
}

package com.cowave.search.common.elasticsearch

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.json.jackson.JacksonJsonpMapper
import co.elastic.clients.transport.rest5_client.Rest5ClientTransport
import co.elastic.clients.transport.rest5_client.low_level.Rest5Client
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.SerializationFeature
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule
import com.fasterxml.jackson.module.kotlin.kotlinModule
import org.apache.hc.core5.http.Header
import org.apache.hc.core5.http.HttpHost
import org.apache.hc.core5.http.message.BasicHeader
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.util.Base64
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap

/**
 * 멀티 클러스터 Elasticsearch 클라이언트 팩토리.
 *
 * - ConcurrentHashMap 기반 클라이언트 캐시
 * - 클러스터 등록/삭제 시 캐시 갱신
 * - Basic 인증 및 ApiKey 인증 지원
 * - 레거시 문제(매 요청마다 클라이언트 생성) 해결
 */
@Component
class ElasticsearchClientFactory {
    private val logger = LoggerFactory.getLogger(ElasticsearchClientFactory::class.java)

    private val clientCache = ConcurrentHashMap<UUID, CachedClusterClient>()

    private val jsonpMapper by lazy {
        val objectMapper =
            ObjectMapper()
                .registerModule(kotlinModule())
                .registerModule(JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
        JacksonJsonpMapper(objectMapper)
    }

    /**
     * clusterId로 ElasticsearchClient 반환.
     * 캐시 미스 시 ClusterInfo로 생성 후 캐시에 저장.
     */
    fun getClient(clusterId: UUID): ElasticsearchClient =
        clientCache[clusterId]?.esClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    /**
     * clusterId로 Rest5Client (Low-Level) 반환.
     * 프록시 등 Low-Level API가 필요한 경우 사용.
     */
    fun getLowLevelClient(clusterId: UUID): Rest5Client =
        clientCache[clusterId]?.restClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    /**
     * 클러스터 등록 (캐시에 클라이언트 추가).
     * 클러스터 CRUD 서비스에서 호출.
     */
    fun registerCluster(info: ClusterConnectionInfo) {
        val cached = buildCachedClient(info)
        clientCache[info.id] = cached
        logger.info("ES 클러스터 등록: {} ({}://{}:{})", info.id, info.scheme, info.host, info.port)
    }

    /**
     * 클러스터 제거 (캐시에서 클라이언트 삭제).
     * 클러스터 삭제 서비스에서 호출.
     */
    fun evictCluster(clusterId: UUID) {
        clientCache.remove(clusterId)?.let {
            runCatching { it.restClient.close() }
                .onFailure { e -> logger.warn("클러스터 클라이언트 종료 실패: $clusterId", e) }
        }
        logger.info("ES 클러스터 제거: {}", clusterId)
    }

    /**
     * 등록된 모든 클러스터 ID 반환.
     */
    fun registeredClusterIds(): Set<UUID> = clientCache.keys.toSet()

    private fun buildCachedClient(info: ClusterConnectionInfo): CachedClusterClient {
        val host = HttpHost.create("${info.scheme}://${info.host}:${info.port}")
        val defaultHeaders = buildAuthHeaders(info)

        val restClient =
            Rest5Client
                .builder(host)
                .setDefaultHeaders(defaultHeaders)
                .build()

        val transport = Rest5ClientTransport(restClient, jsonpMapper)
        val esClient = ElasticsearchClient(transport)

        return CachedClusterClient(restClient, esClient)
    }

    private fun buildAuthHeaders(info: ClusterConnectionInfo): Array<Header> =
        when {
            !info.apiKey.isNullOrBlank() -> {
                arrayOf(BasicHeader("Authorization", "ApiKey ${info.apiKey}"))
            }
            !info.username.isNullOrBlank() && !info.password.isNullOrBlank() -> {
                val credentials = Base64.getEncoder().encodeToString("${info.username}:${info.password}".toByteArray())
                arrayOf(BasicHeader("Authorization", "Basic $credentials"))
            }
            else -> emptyArray()
        }

    private data class CachedClusterClient(
        val restClient: Rest5Client,
        val esClient: ElasticsearchClient,
    )

    /**
     * 클러스터 연결 정보 DTO.
     * Cluster 엔티티에서 변환하여 사용.
     */
    data class ClusterConnectionInfo(
        val id: UUID,
        val scheme: String,
        val host: String,
        val port: Int,
        val username: String? = null,
        val password: String? = null,
        val apiKey: String? = null,
    )
}

package com.cowave.search.notice

import org.slf4j.LoggerFactory
import org.springframework.scheduling.annotation.Async
import org.springframework.stereotype.Service
import org.springframework.web.client.RestClient

/**
 * Telegram Bot API를 통한 알림 서비스.
 *
 * - WebFlux 없이 spring-web의 RestClient 사용
 * - @Async로 비동기 처리 (색인 완료/실패 알림이 주 흐름을 블로킹하지 않도록)
 * - enabled=false 이면 전송 생략
 */
@Service
class TelegramNoticeService(
    private val restClientBuilder: RestClient.Builder,
    private val properties: TelegramProperties,
) {
    private val logger = LoggerFactory.getLogger(TelegramNoticeService::class.java)

    private val restClient: RestClient by lazy { restClientBuilder.build() }

    @Async
    fun sendMessage(text: String) {
        if (!properties.enabled) return
        if (properties.bot.isBlank() || properties.chat.isBlank()) {
            logger.warn("Telegram 설정이 올바르지 않습니다 (bot/chat 미설정)")
            return
        }

        runCatching {
            restClient
                .post()
                .uri("https://api.telegram.org/bot${properties.bot}/sendMessage")
                .body(mapOf("chat_id" to properties.chat, "text" to text))
                .retrieve()
                .toBodilessEntity()
        }.onFailure { e ->
            logger.warn("Telegram 알림 발송 실패: ${e.message}")
        }
    }
}

package com.cowave.search.common.exception

import org.slf4j.LoggerFactory
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice

@RestControllerAdvice
class GlobalExceptionHandler {
    private val logger = LoggerFactory.getLogger(GlobalExceptionHandler::class.java)

    /**
     * DSearch 커스텀 예외 처리.
     * 각 예외 클래스에 정의된 HTTP 상태 코드로 응답한다.
     */
    @ExceptionHandler(DSearchException::class)
    fun handleDSearchException(e: DSearchException): ResponseEntity<Map<String, String>> {
        logger.warn("DSearch exception [${e.status}]: ${e.message}")
        return ResponseEntity.status(e.status).body(mapOf("message" to (e.message ?: "")))
    }

    /**
     * IllegalArgumentException 처리 (레거시 호환).
     */
    @ExceptionHandler(IllegalArgumentException::class)
    fun handleIllegalArgument(e: IllegalArgumentException): ResponseEntity<Map<String, String>> {
        logger.warn("Illegal argument: ${e.message}")
        return ResponseEntity.badRequest().body(mapOf("message" to (e.message ?: "Invalid argument")))
    }

    /**
     * 미처리 예외 처리.
     */
    @ExceptionHandler(Exception::class)
    fun handleException(e: Exception): ResponseEntity<Map<String, String>> {
        logger.error("Unhandled exception", e)
        return ResponseEntity
            .status(HttpStatus.INTERNAL_SERVER_ERROR)
            .body(mapOf("message" to (e.message ?: "Internal server error")))
    }
}

package com.cowave.search.dictionary.controller

import com.cowave.search.dictionary.dto.AllTypesCountResponse
import com.cowave.search.dictionary.dto.AllTypesLastModifiedResponse
import com.cowave.search.dictionary.dto.CompileResult
import com.cowave.search.dictionary.dto.CreateDictionaryRequest
import com.cowave.search.dictionary.dto.CursorPagedResponse
import com.cowave.search.dictionary.dto.SearchColumn
import com.cowave.search.dictionary.dto.SortType
import com.cowave.search.dictionary.dto.TypeCountResponse
import com.cowave.search.dictionary.dto.TypeLastModifiedResponse
import com.cowave.search.dictionary.dto.UpdateDictionaryRequest
import com.cowave.search.dictionary.model.Dictionary
import com.cowave.search.dictionary.model.Type
import com.cowave.search.dictionary.service.DictionaryService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/dictionaries")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    /**
     * 사전 조회/검색 통합 API
     * - word가 없으면 전체 조회
     * - word가 있으면 검색 (searchColumn에 따라 대상 필드 결정)
     */
    @GetMapping("/{type}")
    fun getDictionary(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "20") size: Int,
        @RequestParam(required = false) cursor: String?,
        @RequestParam(defaultValue = "UPDATED") sort: SortType,
        @RequestParam(defaultValue = "ALL") searchColumn: SearchColumn,
        @RequestParam(required = false) word: String?,
        @RequestParam(defaultValue = "false") isMatch: Boolean,
    ): CursorPagedResponse<Dictionary> =
        dictionaryService.search(
            type = type,
            size = size,
            searchColumn = searchColumn,
            word = word,
            isMatch = isMatch,
            cursor = cursor,
            sortType = sort,
        )

    @GetMapping("/{type}/count")
    fun countByType(
        @PathVariable type: Type,
    ): TypeCountResponse = TypeCountResponse(type, dictionaryService.countByType(type))

    @GetMapping("/{type}/last-modified")
    fun getLastModifiedByType(
        @PathVariable type: Type,
    ): TypeLastModifiedResponse = dictionaryService.getLastModifiedByType(type)

    @GetMapping("/last-modified")
    fun getAllTypesLastModified(): AllTypesLastModifiedResponse = dictionaryService.getAllTypesLastModified()

    @GetMapping("/count")
    fun getAllTypesCounts(): AllTypesCountResponse = dictionaryService.getAllTypesCounts()

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @PathVariable id: String,
    ) {
        dictionaryService.delete(id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(type)

    @PostMapping("/compile")
    fun compileAll(): List<CompileResult> = dictionaryService.compileAll()
}
